(async()=>{if(new URLSearchParams(location.search).get('profile')!=='vehicle-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,W=EmberTerrain,D=SurvivalData,V=SurvivalVehicles;document.getElementById('welcome').hidden=true;q.setPlaying(false);const report=document.createElement('pre');report.id='vehicle-report';report.style='position:fixed;inset:0;z-index:10000;overflow:auto;background:#fff;color:#234;padding:20px';document.body.append(report);const results={},check=(k,v)=>{results[k]=v;report.textContent=JSON.stringify(results,null,2);if(!v)throw Error(k);};check('recipesKnown',['car','airplane','motorfuel'].every(id=>D.knows(D.fresh(),id)));
const anchor=W.sites.desert;let best=null;for(let x=anchor.x-800;x<=anchor.x+800;x+=20)for(let z=anchor.z-800;z<=anchor.z+800;z+=20){const y=W.ground(x,z);if(W.nativeBiome(x,z)!=='desert'||y<W.water+4||W.inCave(x,z,y))continue;let score=0;for(let d=0;d<120;d+=10){const h=W.ground(x,z-d),next=W.ground(x,z-d-10);score=Math.max(score,Math.abs(h-next)/10,Math.abs(W.ground(x+5,z-d)-W.ground(x-5,z-d))/10);if(h<W.water+4){score=999;break;}}if(!best||score<best.score)best={x,y,z,score};}check('runwayFound',best&&best.score<.12);q.apply({...D.fresh(),x:best.x,z:best.z+3,y:best.y,yaw:0,worldTime:360,automaticTime:false,inventory:{hammer:1,motorfuel:8,...D.recipes.find(r=>r.id==='car').cost},hand:'hammer'});await wait(1400);check('carPlacement',!V.placement(q.world,q.state,best,'car'));q.deposit('car');const pile=q.state.piles.find(p=>p.items.ore===180);q.craft(pile.id,'car');const job=q.state.jobs.find(j=>j.type==='car');check('carCraftStarted',!!job);q.work(job,120);check('halfBuiltNotDrivable',!q.state.vehicles.length&&job.progress===.5);q.work(job,120);const car=q.state.vehicles[0];check('carBuilt',car?.kind==='car'&&car.fuel===0);let planePoint=null;for(let dx=14;dx<80;dx+=12){const point={x:best.x+dx,y:W.ground(best.x+dx,best.z),z:best.z};if(!V.placement(q.world,q.state,point,'airplane')){planePoint=point;break;}}check('planePlacement',!!planePoint);Object.assign(q.state.inventory,D.recipes.find(r=>r.id==='airplane').cost);Object.assign(q.state,{x:planePoint.x,y:planePoint.y,z:planePoint.z+3,yaw:0});q.deposit('airplane');const airPile=q.state.piles.find(p=>p.items.ore===320);q.craft(airPile.id,'airplane');const airJob=q.state.jobs.find(j=>j.type==='airplane');check('planeCraftStarted',!!airJob);q.work(airJob,480);const plane=q.state.vehicles.find(v=>v.kind==='airplane');check('planeBuilt',!!plane);q.syncObjects();await Promise.all([V.ready('car'),V.ready('airplane')]);await wait(900);check('modelsLoaded',V.registry.get(car.id).userData.ready&&V.registry.get(plane.id).userData.ready);check('blenderMeshes',V.models.get('car').children.length>4&&V.models.get('airplane').children.length>3);
Object.assign(q.state.inventory,D.recipes.find(r=>r.id==='motorfuel').cost);q.deposit('motorfuel');const fuelPile=q.state.piles.find(p=>p.items.spore===6);q.craft(fuelPile.id,'motorfuel');const fuelJob=q.state.jobs.find(j=>j.type==='motorfuel');q.work(fuelJob,20);check('fuelCrafted',q.state.inventory.motorfuel===9);q.vehicleMenu(car);document.querySelector('[data-action="vehiclerefuel:'+car.id+'"]').click();check('refuel',car.fuel===25&&q.state.inventory.motorfuel===8);document.querySelector('[data-action="vehicleboard:'+car.id+'"]').click();q.close(false);q.setPlaying(false);check('boarded',q.state.riding===car.id);for(let i=0;i<120;i++){V.step(q.world,q.state,q.camera,{KeyW:true},.02);if(i%40===0)q.sky.update(q.state,0,true);}check('actualCarMoves',Math.hypot(car.x-best.x,car.z-best.z)>5&&car.fuel<25);for(let i=0;i<100;i++)V.step(q.world,q.state,q.camera,{Space:true},.02);check('brakesStop',car.speed===0);check('exit',!V.leave(q.world,q.state));q.state.checkpoint={id:'vehicle-camp',x:q.state.x,y:q.state.y,z:q.state.z};const savedFuel=car.fuel;check('planeFuel',!V.refuel(q.state,plane));check('planeBoard',!V.mount(q.state,plane));for(let i=0;i<550;i++){V.step(q.world,q.state,q.camera,{KeyW:true,Space:true},.02);if(i%50===0)q.sky.update(q.state,0,true);}check('actualTakeoff',plane.airborne&&plane.y>W.ground(plane.x,plane.z)+10);results.flightAltitude=plane.y-W.ground(plane.x,plane.z);plane.fuel=0;for(let i=0;i<2400&&plane.airborne;i++){V.step(q.world,q.state,q.camera,{},.02);if(i%50===0)q.sky.update(q.state,0,true);}check('actualLanding',!plane.airborne&&Math.abs(plane.y-q.world.floor(plane.x,plane.z,plane.y,q.state))<.05);for(let i=0;i<100;i++)V.step(q.world,q.state,q.camera,{KeyB:true},.02);check('planeExit',!V.leave(q.world,q.state));check('save',q.saveSlot(0));car.fuel=0;check('load',q.loadSlot(0));q.setPlaying(false);check('vehicleSaved',q.state.vehicles[0].fuel===savedFuel&&q.state.vehicles.length===2);check('validSave',D.validSave(q.snapshot()));
const c=q.state.vehicles[0],p=q.state.vehicles[1];Object.assign(p,{...planePoint,yaw:0,pitch:0,roll:0,speed:0,airborne:false});Object.assign(c,{x:best.x,z:best.z,y:best.y,speed:0,pitch:0,roll:0,yaw:0});q.state.riding=null;Object.assign(q.state,{x:best.x+8,z:best.z-10,y:best.y,yaw:2.5,pitch:-.1});q.sky.update(q.state,0,true);q.camera.position.set(best.x+5,best.y+3.1,best.z-6.5);q.camera.lookAt(best.x,best.y+1.25,best.z);await wait(900);const panel=document.createElement('section');panel.id='vehicle-preview';panel.style='position:fixed;inset:0;overflow:auto;background:#fff;z-index:9999;padding:12px';document.body.append(panel);report.style='position:relative;background:#fff;color:#234';panel.append(report);function capture(id){q.renderer.render(q.scene,q.camera);const im=document.createElement('img');im.id=id;im.src=q.renderer.domElement.toDataURL();im.style='width:48%';panel.append(im);}capture('car-preview');q.camera.position.set(p.x+8,p.y+4.5,p.z-9);q.camera.lookAt(p.x,p.y+1.5,p.z);capture('plane-preview');const play=document.createElement('button');play.textContent='乗り物の実物を見る';play.onclick=()=>{panel.hidden=true;q.state.x=c.x+8;q.state.z=c.z-10;q.state.y=c.y;q.state.yaw=2.5;q.state.pitch=-.12;q.setPlaying(true);q.move(0);q.close(false);};panel.prepend(play);const drive=document.createElement('button');drive.textContent='運転メニューを確認';drive.onclick=()=>{panel.hidden=true;q.setPlaying(true);q.vehicleMenu(c);};panel.prepend(drive);results.done=true;report.textContent=JSON.stringify(results,null,2);document.title='乗り物の検証完了';})().catch(e=>{document.title='Vehicle QA error';document.getElementById('vehicle-report').textContent+='\n'+e.stack;});
